<script setup>
import { computed, onMounted, ref } from "vue";
import "./style.css";
const base = import.meta.env.VITE_API_URL || "";
const token = ref(localStorage.getItem("crm_token") || "");
const profile = ref(JSON.parse(localStorage.getItem("crm_profile") || "null"));
const mode = ref("login"), notice = ref(""), bad = ref(""), loading = ref(false), leads = ref([]), users = ref([]), stats = ref({ leads: [], overdueFollowUps: 0, team: [] }), selected = ref(null), history = ref({ activities: [], followUps: [] });
const login = ref({ email: "", password: "" }), signup = ref({ organizationName: "", fullName: "", email: "", password: "" }), lead = ref({ customerName: "", email: "", phone: "", productInterest: "" }), employee = ref({ fullName: "", email: "", password: "", role: "salesperson" }), enquiry = ref({ slug: "", customerName: "", email: "", phone: "", productName: "" }), activity = ref({ type: "call", description: "" }), followup = ref({ dueAt: "", notes: "" });
const admin = computed(() => profile.value?.role === "admin"), manage = computed(() => ["admin", "manager"].includes(profile.value?.role)), counts = computed(() => Object.fromEntries(stats.value.leads.map((x) => [x.status, x.count])));
const publicEnquiryUrl = computed(() => profile.value?.organization_slug ? `${window.location.origin}/?enquiry=${profile.value.organization_slug}` : "");
const say = (text = "", error = false) => { notice.value = error ? "" : text; bad.value = error ? text : ""; };
async function api(path, options = {}) { const headers = { "Content-Type": "application/json", ...options.headers }; if (token.value) headers.Authorization = `Bearer ${token.value}`; const response = await fetch(`${base}${path}`, { ...options, headers }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.message || "Request failed"); return data; }
async function enter() { loading.value = true; say(); try { const data = await api("/api/auth/login", { method: "POST", body: JSON.stringify(login.value) }); token.value = data.accessToken; profile.value = data.profile; localStorage.setItem("crm_token", token.value); localStorage.setItem("crm_profile", JSON.stringify(profile.value)); await load(); say(`Public enquiry form: ${publicEnquiryUrl.value}`); } catch (e) { say(e.message, true); } finally { loading.value = false; } }
async function register() { loading.value = true; say(); try { const data = await api("/api/auth/register", { method: "POST", body: JSON.stringify(signup.value) }); say(`Workspace created. Your public enquiry slug is ${data.organization.slug}. Sign in with ${data.admin.email}.`); mode.value = "login"; } catch (e) { say(e.message, true); } finally { loading.value = false; } }
async function sendEnquiry() { loading.value = true; say(); try { const { slug, ...form } = enquiry.value; await api(`/enquiry/${slug}`, { method: "POST", body: JSON.stringify(form) }); enquiry.value = { slug, customerName: "", email: "", phone: "", productName: "" }; say("Thanks — your enquiry has been sent."); } catch (e) { say(e.message, true); } finally { loading.value = false; } }
async function load() { try { const [dashboard, leadData, userData] = await Promise.all([api("/api/dashboard"), api("/api/leads"), api("/api/users")]); stats.value = dashboard.stats; leads.value = leadData.leads; users.value = userData.users; } catch (e) { say(e.message, true); } }
async function addLead() { try { await api("/api/leads", { method: "POST", body: JSON.stringify(lead.value) }); lead.value = { customerName: "", email: "", phone: "", productInterest: "" }; await load(); say("Lead added."); } catch (e) { say(e.message, true); } }
async function addEmployee() { try { await api("/api/users", { method: "POST", body: JSON.stringify(employee.value) }); employee.value = { fullName: "", email: "", password: "", role: "salesperson" }; await load(); say("Team member created."); } catch (e) { say(e.message, true); } }
async function assign(item, userId) { try { await api(`/api/leads/${item.id}/assign`, { method: "POST", body: JSON.stringify({ userId }) }); await load(); say("Lead assigned."); } catch (e) { say(e.message, true); } }
async function status(item, value) { try { await api(`/api/leads/${item.id}`, { method: "PATCH", body: JSON.stringify({ status: value }) }); await load(); } catch (e) { say(e.message, true); } }
async function open(item) { selected.value = item; activity.value = { type: "call", description: "" }; followup.value = { dueAt: "", notes: "" }; try { history.value = await api(`/api/leads/${item.id}/history`); } catch (e) { say(e.message, true); } }
async function addActivity() { try { await api(`/api/leads/${selected.value.id}/activities`, { method: "POST", body: JSON.stringify(activity.value) }); await open(selected.value); say("Interaction saved."); } catch (e) { say(e.message, true); } }
async function addFollowup() { try { await api(`/api/leads/${selected.value.id}/follow-ups`, { method: "POST", body: JSON.stringify(followup.value) }); await open(selected.value); say("Follow-up scheduled."); } catch (e) { say(e.message, true); } }
async function complete(id) { try { await api(`/api/follow-ups/${id}/complete`, { method: "PATCH" }); await open(selected.value); await load(); } catch (e) { say(e.message, true); } }
function exit() { token.value = ""; profile.value = null; localStorage.removeItem("crm_token"); localStorage.removeItem("crm_profile"); selected.value = null; }
onMounted(() => { const slug = new URLSearchParams(window.location.search).get("enquiry"); if (slug) enquiry.value.slug = slug; if (token.value) load(); });
</script>
<template>
<main><header class="topbar"><strong>LeadFlow</strong><span v-if="profile">{{ profile.full_name }} · {{ profile.role }}</span><button v-if="profile" class="ghost" @click="exit">Sign out</button></header><p v-if="notice" class="notice">{{ notice }}</p><p v-if="bad" class="notice error">{{ bad }}</p>
<section v-if="!profile" class="auth-shell"><div class="card"><h1>{{ mode === 'login' ? 'Sign in to your CRM' : 'Create a CRM workspace' }}</h1><form v-if="mode === 'login'" @submit.prevent="enter"><input v-model="login.email" type="email" placeholder="Work email" required><input v-model="login.password" type="password" placeholder="Password" required><button :disabled="loading">Sign in</button></form><form v-else @submit.prevent="register"><input v-model="signup.organizationName" placeholder="Organization name" required><input v-model="signup.fullName" placeholder="Your full name" required><input v-model="signup.email" type="email" placeholder="Admin email" required><input v-model="signup.password" type="password" minlength="8" placeholder="Password (8+ characters)" required><button :disabled="loading">Create workspace</button></form><button class="link" @click="mode = mode === 'login' ? 'register' : 'login'">{{ mode === 'login' ? 'Create a new workspace' : 'I already have an account' }}</button></div><div class="card"><h2>Public enquiry</h2><p>{{ enquiry.slug ? 'Send an enquiry to this organization.' : 'Enter the organization slug from its public enquiry link.' }}</p><form @submit.prevent="sendEnquiry"><input v-if="!enquiry.slug" v-model="enquiry.slug" placeholder="Organization slug" required><input v-model="enquiry.customerName" placeholder="Your name" required><input v-model="enquiry.email" type="email" placeholder="Email" required><input v-model="enquiry.phone" placeholder="10 digit phone" required><input v-model="enquiry.productName" placeholder="Interested product/service" required><button :disabled="loading">Send enquiry</button></form></div></section>
<section v-else class="workspace"><div class="heading"><div><h1>{{ profile.role === 'manager' ? 'Manager dashboard' : profile.role === 'salesperson' ? 'My leads' : 'Admin dashboard' }}</h1><p>Track leads, conversations, and follow-ups.</p></div><button class="secondary" @click="load">Refresh</button></div><div class="stats"><div><b>{{ leads.length }}</b><span>Visible leads</span></div><div><b>{{ stats.overdueFollowUps }}</b><span>Due follow-ups</span></div><div><b>{{ counts.won || 0 }}</b><span>Won</span></div><div><b>{{ counts.qualified || 0 }}</b><span>Qualified</span></div></div><div v-if="profile.role === 'manager'" class="card"><h2>Salesperson workload</h2><div class="workload" v-for="member in stats.team" :key="member.full_name"><span>{{ member.full_name }}</span><b>{{ member.lead_count }} leads</b></div><p v-if="!stats.team.length">No salespeople have been added yet.</p></div><div class="two"><form v-if="manage" class="card" @submit.prevent="addLead"><h2>Add lead</h2><input v-model="lead.customerName" placeholder="Customer name" required><input v-model="lead.email" type="email" placeholder="Email"><input v-model="lead.phone" placeholder="Phone" required><input v-model="lead.productInterest" placeholder="Product interest"><button>Add lead</button></form><form v-if="admin" class="card" @submit.prevent="addEmployee"><h2>Add team member</h2><input v-model="employee.fullName" placeholder="Full name" required><input v-model="employee.email" type="email" placeholder="Email" required><input v-model="employee.password" type="password" minlength="8" placeholder="Temporary password" required><select v-model="employee.role"><option value="salesperson">Salesperson</option><option value="manager">Manager</option></select><button>Create account</button></form></div><section class="card leads"><h2>Leads</h2><p v-if="!leads.length">No leads yet. Public enquiries and manual leads appear here.</p><div v-for="item in leads" :key="item.id" class="lead-row"><button class="lead-name" @click="open(item)"><b>{{ item.customer_name }}</b><small>{{ item.product_interest || 'No product selected' }} · {{ item.phone }}</small></button><select :value="item.status" @change="status(item, $event.target.value)"><option v-for="state in ['new','contacted','qualified','won','lost']" :key="state" :value="state">{{ state }}</option></select><select v-if="manage" :value="item.assigned_to || ''" @change="assign(item, $event.target.value)"><option value="" disabled>Assign to…</option><option v-for="person in users.filter((x) => x.role !== 'admin' && (profile.role === 'admin' || x.role === 'salesperson'))" :key="person.id" :value="person.id">{{ person.full_name }} ({{ person.role }})</option></select><span v-else>{{ item.assigned_name || 'Unassigned' }}</span></div></section></section>
<div v-if="selected" class="modal" @click.self="selected = null"><section class="detail"><button class="close" @click="selected = null">×</button><h2>{{ selected.customer_name }}</h2><p>{{ selected.email || 'No email' }} · {{ selected.phone }}</p><div class="two"><form @submit.prevent="addActivity"><h3>Interaction</h3><select v-model="activity.type"><option value="call">Call</option><option value="meeting">Meeting</option><option value="email">Email</option><option value="note">Note</option></select><textarea v-model="activity.description" placeholder="What happened?" required></textarea><button>Save interaction</button></form><form @submit.prevent="addFollowup"><h3>Follow-up</h3><input v-model="followup.dueAt" type="datetime-local" required><textarea v-model="followup.notes" placeholder="Notes"></textarea><button>Schedule</button></form></div><h3>History</h3><div v-for="item in history.activities" :key="item.id" class="history"><b>{{ item.activity_type }}</b><span>{{ item.description }}</span><small>{{ new Date(item.created_at).toLocaleString() }}</small></div><h3>Follow-ups</h3><div v-for="item in history.followUps" :key="item.id" class="history"><span>{{ new Date(item.due_at).toLocaleString() }} · {{ item.notes || 'No notes' }}</span><button v-if="item.status === 'pending'" class="tiny" @click="complete(item.id)">Complete</button><small>{{ item.status }}</small></div></section></div></main>
</template>
